const now = new Date();
const end = now.toISOString();
const startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const start = startDate.toISOString();
const config = { config_version: 'g8n.france-travail.search.v1', run_mode: 'dry_run', zone: { mode: 'france_entire', region: null, departement: null, commune: null }, publication_window: { start_utc: start, end_utc: end }, job_filters: { keywords: ['formation', 'recrutement', 'alternance', 'commercial B2B'], rome_codes: ['K2111', 'M1502', 'D1402'], contract_types: ['CDI', 'CDD', 'MIS', 'FRA'] }, batch: { range: '0-49', max_results: 50 } };
return [{ json: { run_id: `ft_manual_${end.replace(/[-:.]/g, '').slice(0, 15)}Z`, correlation_id: `ft_manual_${end.replace(/[-:.]/g, '').slice(0, 15)}Z`, schema_version: 'g8n.workflow-envelope.v1', source: { workflow_id: 'WF-10', workflow_name: 'WF-10 — France Travail manual search dry-run', node_name: 'Build — Default search config', origin: 'manual_local' }, timestamps: { received_at: end, started_at: end, finished_at: null }, payload: { config, overrides: {}, france_travail_query: null }, metadata: { environment: $env.G8N_ENVIRONMENT || 'local', fixture: String($env.G8N_MOCK_MODE || 'false').toLowerCase() === 'true', retry_count: 0 } } }];

const input = $input.first().json;
const cfg = input.payload.config;
const start = new Date(cfg.publication_window.start_utc);
const end = new Date(cfg.publication_window.end_utc);
const rangeEnd = Number(String(cfg.batch.range).split('-')[1] || '0');
const errors = [];
if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || start > end) errors.push({ code: 'G8N_FT_INVALID_WINDOW', category: 'validation', message: 'Publication window is invalid or inverted.', recoverable: true, masked: true });
if (rangeEnd + 1 > 100) errors.push({ code: 'G8N_FT_BATCH_TOO_LARGE', category: 'validation', message: 'Manual run batch exceeds hard limit.', recoverable: true, masked: true });
const params = { motsCles: cfg.job_filters.keywords.join(' '), range: cfg.batch.range, sort: 'date' };
if (cfg.zone.region) params.region = cfg.zone.region;
if (cfg.zone.departement) params.departement = cfg.zone.departement;
if (cfg.zone.commune) params.commune = cfg.zone.commune;
return [{ json: { ...input, status: errors.length ? 'error' : 'success', payload: { ...input.payload, france_travail_query: params, summary: { mode: cfg.run_mode, zone: cfg.zone.mode === 'france_entire' ? 'France entière' : cfg.zone, window_start_utc: cfg.publication_window.start_utc, window_end_utc: cfg.publication_window.end_utc, max_results: cfg.batch.max_results, config_version: cfg.config_version, dry_run: cfg.run_mode === 'dry_run' } }, timestamps: { ...input.timestamps, finished_at: new Date().toISOString() }, errors } }];
